#!/bin/bash

# This script is only for: 
# Exome Sequencing analysis of paired-end short read sequencing data generated by Illumina sequencers
# varinat calling and annotation is for SNP detection 
# CNV analysis and structural variant analysis has separate scripts
# this script is based on hg38 reference genome, for other reference genomes,
# WHOLE pipeline must be revised


###############################################################################
# set sample directory (sample_dir)
# set ngs data directory (ngsdb)
# set number of threads according to your system CPU architectire
# set tranch filter level after vqsr
###############################################################################

sample_dir="/mnt/hgfs/sharefolder/project_ES_Sana"
ngsdb="/mnt/hgfs/sharefolder/ngsdb"
threads=12
tranch_filter_level=99

reference_hg38="$ngsdb/gatk-hg38/Homo_sapiens_assembly38.fasta"

bqsr_1000g=""
bqsr_omni="$ngsdb/gatk-hg38/1000G_omni2.5.hg38.vcf.gz"
bqsr_hapmap="$ngsdb/gatk-hg38/hapmap_3.3.hg38.vcf.gz"
bqsr_dbsnp="$ngsdb/gatk-hg38/Homo_sapiens_assembly38.dbsnp138.vcf"
bqsr_known_indel="$ngsdb/gatk-hg38/Homo_sapiens_assembly38.known_indels.vcf.gz"
bqsr_mills_indel="$ngsdb/gatk-hg38/Mills_and_1000G_gold_standard.indels.hg38.vcf.gz"

vqsr_hapmap="$ngsdb/gatk-hg38/hapmap_3.3.hg38.vcf.gz"
vqsr_omni="$ngsdb/gatk-hg38/1000G_omni2.5.hg38.vcf.gz"
vqsr_1000g=""
vqsr_dbsnp="$ngsdb/gatk-hg38/Homo_sapiens_assembly38.dbsnp138.vcf"
vqsr_mills_indel="$ngsdb/gatk-hg38/Mills_and_1000G_gold_standard.indels.hg38.vcf.gz"
vqsr_axion="$ngsdb/gatk-hg38/Axiom_Exome_Plus.genotypes.all_populations.poly.hg38.vcf.gz"

annovar_data="/home/happy/annovar_data/"

###############################################################################
# Creating the FASTA sequence dictionary and index file 
###############################################################################
if [ -f "$ngsdb/gatk-hg38/Homo_sapiens_assembly38.dict" ]; then
	echo " Sequnce dictionary for gatk has been made already "
else
	gatk CreateSequenceDictionary -R $reference_hg38
	echo " gatk has made dictionary for reference sequence "
fi


if [ -f "$reference_hg38.fai" ]; then
	echo " Index for samtools has been made already "
else
	samtools faidx $reference_hg38
	echo " samtools made index for reference sequence "
fi


if [ -f "$reference_hg38.bwt" ]; then
	echo " Index for bwa has been made already "
else
	bwa index -a bwtsw $reference_hg38
	echo " BWA has made index for reference sequence "
fi


###############################################################################
# make directory in sample directory for better organization of files
###############################################################################
if [ -d "${sample_dir}/raw_data/" ] \
	&& [ -d "${sample_dir}/annotation_filtering/" ] \
	&& [ -d "${sample_dir}/fastq_after_QC/" ] \
	&& [ -d "${sample_dir}/alignment_postalignment/" ] \
	&& [ -d "${sample_dir}/raw_vcf/" ] \
	&& [ -d "${sample_dir}/patient_phenotype/" ] \
	&& [ -d "${sample_dir}/final_report" ]; then
	echo " Sub directories has been made already "
else
	mkdir \
		${sample_dir}/raw_data \
		${sample_dir}/annotation_filtering \
		${sample_dir}/fastq_after_QC \
		${sample_dir}/alignment_postalignment \
		${sample_dir}/raw_vcf \
		${sample_dir}/patient_phenotype \
		${sample_dir}/final_report
	echo " Sub directories has been made "
fi


##############################################################################
# check raw file format
##############################################################################
# Check if files are compressed
if find ${sample_dir} -maxdepth 1 -type f | grep -q .; then
	if find ${sample_dir} -maxdepth 1 -type f -name "*.gz" | grep -q . ; then
		echo " Raw fastq files are compressed "
		mv ${sample_dir}/*.gz ${sample_dir}/raw_data/
		echo " Raw fastq files moved to ${sample_dir}/raw_data "
	else
		echo " Start comperssing raw files for memory efficiency "
		pigz -p $threads ${sample_dir}/*.fastq
		mv ${sample_dir}/*.gz ${sample_dir}/raw_data/
		echo " Raw fastq files moved to ${sample_dir}/raw_data "
	fi
elif find ${sample_dir}/raw_data -type f | grep -q .; then
	echo " Sample files are ready "
else
	echo " Please copy and extract raw data in ${sample_dir}"
	echo " Run script after providing raw data "
	exit
fi


# Rename sample files to sample_R1 and sample_R2
if find ${sample_dir}/raw_data/ -type f | grep -qE 'R1|R2'  ; then
	if find ${sample_dir}/raw_data/ -type f | grep -qE 'sample_R1.fastq.gz|sample_R2.fastq.gz'; then
		echo " Sample names are OK"
	else
		mv ${sample_dir}/raw_data/*R1* ${sample_dir}/raw_data/sample_R1.fastq.gz
		mv ${sample_dir}/raw_data/*R2* ${sample_dir}/raw_data/sample_R2.fastq.gz
		echo " Sample name has been renamed to sample_R1.fastq.gz and sample_R2.fastq.gz "
	fi
elif find ${sample_dir}/raw_data/ -type f | grep -qE '*1*.*.gz|*2*.*.gz' ; then
	if find ${sample_dir}/raw_data/ -type f | grep -qE 'sample_R1.fastq.gz|sample_R2.fastq.gz'; then
		echo " Sample names are OK"
	else
		mv ${sample_dir}/raw_data/*1*.*.gz ${sample_dir}/raw_data/sample_R1.fastq.gz
		mv ${sample_dir}/raw_data/*2*.*.gz ${sample_dir}/raw_data/sample_R2.fastq.gz
		echo " Sample name has been renamed to sample_R1.fastq.gz and sample_R2.fastq.gz "
	fi
else
	echo " Rename raw files manually to sample_R1.fastq.gz and sample_R2.fastq.gz "
	echo " Run script after renaming "
	exit
fi


###############################################################################
# fastq quality control 
###############################################################################
# quality control of raw fastq files
if find ${sample_dir}/raw_data/ -type f -name "*fastqc*" | grep -q fastqc; then
	echo " FastQC reports are ready "
else
	fastqc -q -t $threads ${sample_dir}/raw_data/*.gz
       	echo " FastQC reports has been generated "
fi

echo " Raw fastq quality control: "
echo " Check fastQC reports in ${sample_dir}/raw_data/"
echo " Enter 'yes' if raw fastq QC is ok "
read -p " Enter 'done' if you have done trimming manually " qc_is_ok


# simple fastp output // no trimming // removing low quality reads and reads with length below fastp defualt 
if [ $qc_is_ok == yes ]; then
	if find ${sample_dir}/fastq_after_QC/ -type f -name "*report*" | grep -q report; then
		echo " fastp reports are ready "
	else
		fastp \
			-j ${sample_dir}/fastq_after_QC/report.json \
			-h ${sample_dir}/fastq_after_QC/report.html \
			-i ${sample_dir}/raw_data/sample_R1.fastq.gz \
			-o ${sample_dir}/fastq_after_QC/read_1.fastq.gz \
			-I ${sample_dir}/raw_data/sample_R2.fastq.gz \
			-O ${sample_dir}/fastq_after_QC/read_2.fastq.gz 
		echo " fastp reports has been generated "
	fi
	
	
	if find ${sample_dir}/fastq_after_QC/ -type f -name "*fastqc*" | grep -q fastqc; then
		echo " FastQC reports after fastp are ready "
	else
		fastqc -q -t $threads  ${sample_dir}/fastq_after_QC/read_?.fastq.gz
		echo " FastQC reports after fastp has been generated "
	fi
	echo " fastp report and FastQC after fastp available in ${sample_dir}/fasq_after_qc/ directory"
elif [ $qc_is_ok == done ]; then
	if find ${sample_dir}/fastq_after_QC/ -type f -name "*report*" | grep -q report; then
		echo " fastp reports are ready "
		echo " Continue "
	else
		echo " provide reads after fastp as instructed "
	fi	
else
	echo " Change fastp options manually and then save results to fastq_after_qc directory "
	echo " name of file must be read_1.fastq.gz and read_2.fastq.gz."
	echo " run again"
	exit
fi


###############################################################################
# Data pre processing
# alignment, post alignment and BQSR
###############################################################################
# alignment
echo " Estimated time of alignment is 1 hour "
read -p " Do you want to proceed? (Press y): " a_proceed
if [ $a_proceed == y ]; then
	if [ -f "${sample_dir}/alignment_postalignment/aligned.sam" ] || \
      [ -f "${sample_dir}/alignment_postalignment/after_md.bam" ]; then
		echo " Sam file has been generated already "
	else
		bwa mem \
			-t $threads \
		    $reference_hg38 \
            ${sample_dir}/fastq_after_QC/read_1.fastq.gz \
			${sample_dir}/fastq_after_QC/read_2.fastq.gz \
			> ${sample_dir}/alignment_postalignment/aligned.sam
		echo " Alignment has been done and sam file has been generated "
	fi
else
	exit
fi


# post alignment 
echo " Estimated time of post alignment processes is 25 minutes "
read -p " Do you want to proceed? (Press y): " pa_proceed
if [ $pa_proceed == y ]; then
	if [ -f "${sample_dir}/alignment_postalignment/after_md.bai" ]; then
		echo " Post alignment processes has been done already "
	else
		gatk SortSam \
			-I ${sample_dir}/alignment_postalignment/aligned.sam \
			-O ${sample_dir}/alignment_postalignment/after_sort.bam \
			-SO coordinate

		echo " gatk SortSam has done "

		gatk AddOrReplaceReadGroups \
			-I ${sample_dir}/alignment_postalignment/after_sort.bam \
			-O ${sample_dir}/alignment_postalignment/after_rg.bam \
			-ID HTYYCBBXX.1.CH_plate1_A01 \
			-SM CH_plate1_A01 \
			-LB Lib-1  \
			-PU HTYYCBBXX.1.TCAATCCG+TTCGCAGT \
			-PL ILLUMINA

		echo " gatk AddOrReplaceReadGroups has done"

		gatk MarkDuplicates \
			-I ${sample_dir}/alignment_postalignment/after_rg.bam \
			-O ${sample_dir}/alignment_postalignment/after_md.bam \
			-M ${sample_dir}/alignment_postalignment/report_md.txt

		echo " gatk MarkDuplicates has done "
		
		gatk BuildBamIndex \
			-I ${sample_dir}/alignment_postalignment/after_md.bam \
			-O ${sample_dir}/alignment_postalignment/after_md.bai

		echo " gatk BuildBamIndex has done "
	fi
else
	exit
fi


# Remove extra sam and bam files (optional)
read -p " Do you wanna remove aligned.sam after_sort.bam after_rg.bam files and freeup memory space? (Press y/n): " rm_choice
if [ $rm_choice == y ]; then
	rm -f ${sample_dir}/alignment_postalignment/after_sort.bam \
		${sample_dir}/alignment_postalignment/after_rg.bam \
		${sample_dir}/alignment_postalignment/aligned.sam
else
	echo " continue without file removal " 
fi


# alignment quality control 
read -p " Do you wanna generate post alignment QC reports? (Press y/n): " pa_qc_choice
if [ $pa_qc_choice == y ]; then
	gatk CollectAlignmentSummaryMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-casm.txt \
		-R $reference_hg38

	gatk CollectQualityYieldMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cqym.txt \
		-R $reference_hg38
	
	gatk CollectBaseDistributionByCycle \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cbdbc.txt \
		-R $reference_hg38 \
		-CHART ${sample_dir}/alignment_postalignment/report-cbdbc.pdf
	
	gatk CollectGcBiasMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cgcbm.txt \
		-R $reference_hg38 \
		-CHART ${sample_dir}/alignment_postalignment/report-cgcbm.pdf \
		-S ${sample_dir}/alignment_postalignment/report-cgcbm_s.txt
	
	gatk CollectInsertSizeMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cism.txt \
		-R $reference_hg38 \
		-H ${sample_dir}/alignment_postalignment/report-cism.pdf \
		-M 0.05
	
	gatk CollectOxoGMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cogm.txt \
		-R $reference_hg38 

	gatk MeanQualityByCycle \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-mqbc.txt \
		-R $reference_hg38 \
		-CHART ${sample_dir}/alignment_postalignment/report-mqbc.pdf

	gatk CollectJumpingLibraryMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-cjlm.txt \
		-R $reference_hg38

	gatk CollectSequencingArtifactMetrics \
		-I ${sample_dir}/alignment_postalignment/after_md.bam \
		-O ${sample_dir}/alignment_postalignment/report-csam.txt \
		-R $reference_hg38

	echo " All post alignment quality control has been done "
else
	echo " Post alignment QC skipped "
fi


# BQSR 
echo " BQSR estimated time is 40 minutes "
read -p " Do you wanna proceed? (Press y/n): " bqsr_proceed
if [ $bqsr_proceed == y ]; then
	if [ -f "${sample_dir}/alignment_postalignment/report-bqsr.csv" ]; then
        echo " BQSR has been done already "
    else
        gatk BaseRecalibrator \
            -I ${sample_dir}/alignment_postalignment/after_md.bam \
            -O ${sample_dir}/alignment_postalignment/bqsr_1.recall \
            -R $reference_hg38 \
            --known-sites $bqsr_omni \
            --known-sites $bqsr_dbsnp \
            --known-sites $bqsr_hapmap \
            --known-sites $bqsr_known_indel \
            --known-sites $bqsr_mills_indel

        gatk ApplyBQSR \
            -I ${sample_dir}/alignment_postalignment/after_md.bam \
            -bqsr ${sample_dir}/alignment_postalignment/bqsr_1.recall \
            -O ${sample_dir}/alignment_postalignment/after_bqsr.bam \
            -R $reference_hg38 

        gatk BaseRecalibrator \
            -I ${sample_dir}/alignment_postalignment/after_bqsr.bam \
            -O ${sample_dir}/alignment_postalignment/bqsr_2.recall \
            -R $reference_hg38 \
            --known-sites $bqsr_omni \
            --known-sites $bqsr_dbsnp \
            --known-sites $bqsr_hapmap \
            --known-sites $bqsr_known_indel \
            --known-sites $bqsr_mills_indel

        gatk AnalyzeCovariates \
            -before ${sample_dir}/alignment_postalignment/bqsr_1.recall \
            -after ${sample_dir}/alignment_postalignment/bqsr_2.recall \
            -plots ${sample_dir}/alignment_postalignment/report-bqsr.pdf \
            -csv ${sample_dir}/alignment_postalignment/report-bqsr.csv 

        echo "BQSR is done"
    fi
else
	exit
fi


###############################################################################
# variant calling with gatk HaplotypeCaller
###############################################################################
echo " HaplotypeCaller estimated time is 1 hour "
read -p " Do you want to do variant calling? (Press y/n): " hc_proceed
if [ $hc_proceed == y ]; then
	if [ -f "${sample_dir}/raw_vcf/raw_vcf.vcf" ]; then
        echo " variant calling has been done already "
    else
        gatk HaplotypeCaller \
            -I ${sample_dir}/alignment_postalignment/after_bqsr.bam \
            -O ${sample_dir}/raw_vcf/raw_vcf.vcf \
            -R $reference_hg38
        echo " variant calling is done "
    fi
else
	exit
fi


###############################################################################
# VQSR
############################################################################### 
# VQSR-SNP
read -p " Do you want to do VQSR? (Press y/n): " vqsr_proceed
if [ $vqsr_proceed == y ]; then
    if [ -f "${sample_dir}/raw_vcf/vqsr-snp.vcf" ]; then
        echo " VQSR has been done already "
    else
        gatk VariantRecalibrator \
            -mode SNP \
            -V ${sample_dir}/raw_vcf/raw_vcf.vcf \
            -O ${sample_dir}/raw_vcf/vqsr-snp.vcf \
            -R $reference_hg38 \
            --tranches-file ${sample_dir}/raw_vcf/snp-tranch.tranches \
            -tranche 100 \
            -tranche 99.9 \
            -tranche 99 \
            -tranche 90 \
            -an QD \
            -an MQ \
            -an MQRankSum \
            -an ReadPosRankSum \
            -an FS \
            -an SOR \
            --rscript-file ${sample_dir}/raw_vcf/report-vqsr-snp.R \
            --resource:hapmap,truth=true,training=true,known=false,prior=15 $vqsr_hapmap \
            --resource:omni,truth=true,training=true,known=false,prior=12 $vqsr_omni \
            --resource:dbsnp,truth=false,training=false,known=true,prior=2 $vqsr_dbsnp
        
        echo " VQSR has been done already "
    fi
else
	exit
fi


read -p " Please check tranche files and set tranch_filter_level (Enter 'set' to continue): " avqsr_proceed
if [ $avqsr_proceed == set ]; then
    if [ -f "${sample_dir}/raw_vcf/after-vqsr-snp.vcf" ]; then
        echo " ApplyVQSR has been done already "
    else
        gatk ApplyVQSR \
            -mode SNP \
            -V ${sample_dir}/raw_vcf/raw_vcf.vcf \
            --recal-file ${sample_dir}/raw_vcf/vqsr-snp.vcf \
            --tranches-file ${sample_dir}/raw_vcf/snp-tranch.tranches \
            -ts-filter-level $tranch_filter_level \
            -O ${sample_dir}/raw_vcf/after-vqsr-snp.vcf 
        echo " ApplyVQSR has been done "
        echo " Your vcf is ready for annotation "	
    fi
else
	exit
fi


###############################################################################
# variants check 
###############################################################################
read -p " Do you want to generate report of variants in raw vcf? (Press y/n): " raw_vcf_qc
if [ $raw_vcf_qc == y ]; then
    if [ -f "${sample_dir}/raw_vcf/report-bcftools-snp.txt" ]; then
        echo " Reports of raw vcf variants are ready "
    else
        gatk CountVariants \
            -V ${sample_dir}/raw_vcf/after-vqsr-snp.vcf 

        bcftools stats \
            ${sample_dir}/raw_vcf/after-vqsr-snp.vcf  \
            > ${sample_dir}/raw_vcf/report-bcftools-snp.txt 

        # validatevariants only runs if something goes wrong it will show error, else it only runs
        gatk ValidateVariants \
            -V ${sample_dir}/raw_vcf/after-vqsr-snp.vcf \
            -R $reference_hg38 \
            --dbsnp $bqsr_dbsnp
        
        echo " raw vcf is fine and reports are ready in ${sample_dir}/raw_vcf/ "
   fi
fi


###############################################################################
# annotation 
###############################################################################
echo " Annotation time is 45 minutes "
read -p " Do you want to annotate raw vcf by dafault options? (Press y/n): " annotate
if [ $annotate == y ]; then
	if [ -f ${sample_dir}/annotation_filtering/after_anno.vcf ]; then
		echo " Annotated vcf has been generate already "
	else
		table_annovar.pl \
			${sample_dir}/raw_vcf/after-vqsr-snp.vcf \
            ${annovar_data}/humandb/ \
            -v \
			--remove \
			--buildver hg38 \
			--outfile ${sample_dir}/annotation_filtering/after_anno.vcf \
			--vcfinput \
			--nastring . \
			--protocol  refGene,knownGene,ensGene,dbnsfp47a,intervar_20250721,logofunc,gnomad41_exome,regeneron,allofus,revel,avsnp151,clinvar_20250721 \
			--operation gx,g,g,f,f,f,f,f,f,f,f,f \
			--xreffile ${annovar_data}/example/gene_xref.txt \
            --thread $threads \
            --nopolish

		echo " Annotation is done "
	fi
else
	exit
fi

echo " Fastq --> annotated vcf is done, now you can start filtering variants "
